import { HEADING_FONT_SIZES, PARAGRAPH_FONT_SIZE } from './../../ricos-styles/theme-constants.js';

/**
 * Default typography font-size (px) of a list item's text block — the paragraph
 * default, or the heading level's default when the first child is a heading.
 *
 * Used as the threshold for shrinking the child block's font: a chosen font-size
 * mark smaller than this leaves the block's own strut (and the list marker)
 * oversized, so the child paragraph/heading is made to adopt the chosen size
 * instead — see `list-checkbox.scss` and the `list-item-sizing` decoration.
 */
export const getBlockDefaultFontSize = (headingLevel?: number): number =>
  parseFloat(
    headingLevel
      ? HEADING_FONT_SIZES[`h${headingLevel}` as keyof typeof HEADING_FONT_SIZES]
      : PARAGRAPH_FONT_SIZE
  );
