// Shallow lodash.omit replacement for dynamic key lists (for statically known
// keys prefer rest destructuring). Tolerates nullish objects like lodash did.
export function omitKeys<T extends object>(
  obj: T | null | undefined,
  keys: readonly string[]
): Partial<T> {
  return Object.fromEntries(
    Object.entries(obj ?? {}).filter(([key]) => !keys.includes(key))
  ) as Partial<T>;
}
