/**
 * Determines whether a media upload comes from a custom source (uploaded via the Media Manager)
 * or from an external URL (e.g., YouTube).
 *
 * Typically, custom uploads set `src.id`, while external URLs set `src.url`.
 * However, the Media Manager in Wixel also returns `src.url` for custom uploads.
 * Therefore, this function checks whether the URL points to Wix-hosted media
 * to correctly distinguish between the two cases.
 */
export const isCustomUpload = (url: string | undefined) =>
  url &&
  (url.startsWith('https://music.wixstatic.com/mp3') ||
    url.startsWith('https://video.wixstatic.com/video'));
