// Splits an identifier into words the way lodash's case helpers do for the
// ASCII inputs ricos uses: 'LINK_PREVIEW' → ['LINK', 'PREVIEW'],
// 'imageGallery' → ['image', 'Gallery'], 'image-gallery' → ['image', 'gallery'].
export function splitWords(str: string): string[] {
  return (
    str.match(/[A-Z]{2,}(?=[A-Z][a-z]|\b|[^a-zA-Z0-9])|[A-Z]?[a-z]+[0-9]*|[A-Z]+|[0-9]+/g) ?? []
  );
}
