/**
 * Elements that can take keyboard focus. An approximation of what `tabbable`
 * (and therefore `focus-trap`) considers focusable — it does not account for
 * visibility, `inert`, or shadow roots — so use it to ask "is there anything
 * focusable here yet", not to decide where focus must land.
 */
export const FOCUSABLE_SELECTOR =
  'a[href], button:not([disabled]), input:not([disabled]), textarea:not([disabled]), select:not([disabled]), details, [tabindex]:not([tabindex="-1"]):not([disabled])';
