// Structural equality for the JSON-like data ricos compares (content nodes,
// decorations, themes). Mirrors the lodash.isEqual behavior our call sites rely
// on: NaN equals NaN, Dates compare by time, arrays/plain objects recurse.
// The optional customizer covers the lodash.isEqualWith use case: it is invoked
// for every pair with the property key/index the pair was reached through
// (undefined at the top level); returning a boolean short-circuits, `undefined`
// falls through to the default comparison.
export function deepEqual(
  a: unknown,
  b: unknown,
  customizer?: (a: unknown, b: unknown, key?: PropertyKey) => boolean | undefined,
  key?: PropertyKey
): boolean {
  if (customizer) {
    const custom = customizer(a, b, key);
    if (custom !== undefined) {
      return custom;
    }
  }
  if (a === b) {
    return true;
  }
  if (typeof a === 'number' && typeof b === 'number') {
    return Number.isNaN(a) && Number.isNaN(b);
  }
  if (a instanceof Date || b instanceof Date) {
    return a instanceof Date && b instanceof Date && a.getTime() === b.getTime();
  }
  if (typeof a !== 'object' || typeof b !== 'object' || a === null || b === null) {
    return false;
  }
  if (Array.isArray(a) !== Array.isArray(b)) {
    return false;
  }
  if (Array.isArray(a) && Array.isArray(b)) {
    return a.length === b.length && a.every((item, i) => deepEqual(item, b[i], customizer, i));
  }
  const aKeys = Object.keys(a);
  const bKeys = Object.keys(b);
  return (
    aKeys.length === bKeys.length &&
    aKeys.every(
      key =>
        Object.prototype.hasOwnProperty.call(b, key) &&
        deepEqual(
          (a as Record<string, unknown>)[key],
          (b as Record<string, unknown>)[key],
          customizer,
          key
        )
    )
  );
}
