import type { TiptapEditor } from './../ricos-types/index.js';
import { minMax } from './../tiptap/index.js';
import type { Editor } from './../tiptap/core/index.js';
import type { EditorView } from './../tiptap/pm/view.js';

// Custom posToDOMRect that adjusts horizontal properties to match editor width
// This is similar to https://github.com/ueberdosis/tiptap/blob/4474d056daf9280ebb10b31f98bb000e953132e5/packages/core/src/helpers/posToDOMRect.ts#L5
// However we adjust actual horizontal properties with editor dimensions
export const posToDOMRect = (view: EditorView, from: number, to: number): DOMRect => {
  const rootLevelNodePosition = view.state.selection.$from.before(1);
  const nodeDOM = view.nodeDOM(rootLevelNodePosition);
  const referenceElement = nodeDOM instanceof Element ? nodeDOM : view.dom;

  const editorRect = referenceElement.getBoundingClientRect();
  const minPos = 0;
  const maxPos = view.state.doc.content.size;
  const resolvedFrom = minMax(from, minPos, maxPos);
  const resolvedEnd = minMax(to, minPos, maxPos);
  const start = view.coordsAtPos(resolvedFrom);
  const end = view.coordsAtPos(resolvedEnd, -1);
  const top = Math.min(start.top, end.top);
  const bottom = Math.max(start.bottom, end.bottom);
  const left = editorRect.left;
  const right = editorRect.right;
  const width = right - left;
  const height = bottom - top;
  const x = left;
  const y = top;
  const data = {
    top,
    bottom,
    left,
    right,
    width,
    height,
    x,
    y,
  };

  return {
    ...data,
    toJSON: () => data,
  };
};

export type FakeReferenceElement = {
  getBoundingClientRect: () => DOMRect;
  focus: () => void;
};

// Creates a virtual reference element for floating-ui positioning
export const getFakeReferenceElement = (editor: TiptapEditor | Editor): FakeReferenceElement => {
  const { view } = editor;
  const { from, to } = view.state.selection;

  return {
    getBoundingClientRect: () => posToDOMRect(view, from, to),
    focus: () => view.focus(),
  };
};
