import { debounce } from './/debounce.js';

type ElementSize = { width: number; height: number };

/**
 * Observes an element with a native `ResizeObserver` and reports its
 * `getBoundingClientRect()` width/height whenever it changes (and once
 * immediately on observe). Returns a cleanup function. No-ops during SSR or
 * where `ResizeObserver` is unavailable. Replaces `react-measure`.
 */
export const observeElementSize = (
  element: Element,
  onResize: (size: ElementSize) => void,
  { debounceMs = 0 }: { debounceMs?: number } = {}
): (() => void) => {
  if (typeof window === 'undefined' || !window.ResizeObserver) {
    return () => {};
  }

  const emit = () => {
    const { width, height } = element.getBoundingClientRect();
    onResize({ width, height });
  };

  const debounced = debounceMs > 0 ? debounce(emit, debounceMs) : undefined;
  const handler = debounced ?? emit;

  const observer = new ResizeObserver(() => handler());
  observer.observe(element);

  return () => {
    observer.disconnect();
    debounced?.cancel();
  };
};
