import { MediaUploadErrorKey, type UpdateEntityFileUploadFunc } from './../ricos-content/index.js';

export type UploadFunction<T> = (
  file: File,
  updateEntity: UpdateEntityFileUploadFunc<T>
) => Promise<void> | void;

export const withFileSizeLimitation = <T>(
  uploadFunction: UploadFunction<T>,
  fileUploadSizeLimit: number | undefined
): UploadFunction<T> => {
  return (file: File, updateEntity: UpdateEntityFileUploadFunc<T>) =>
    isFileSizeExcceeded(file, fileUploadSizeLimit)
      ? updateEntity({
          error: {
            key: MediaUploadErrorKey.SIZE_LIMIT,
            args: { maxLimit: fileUploadSizeLimit },
          },
        })
      : uploadFunction(file, updateEntity);
};

function isFileSizeExcceeded(
  file: File,
  fileUploadSizeLimit?: number
): fileUploadSizeLimit is number {
  return !!fileUploadSizeLimit && file.size >= fileUploadSizeLimit * 1024 * 1024;
}
