import { splitWords } from './split-words.js';

// lodash.camelCase for the ASCII identifiers ricos converts (node types,
// plugin keys): 'IMAGE' → 'image', 'LINK_PREVIEW' → 'linkPreview',
// 'image-gallery' → 'imageGallery'.
export function toCamelCase(str: string | undefined): string {
  return splitWords(str ?? '')
    .map((word, i) =>
      i === 0 ? word.toLowerCase() : word.charAt(0).toUpperCase() + word.slice(1).toLowerCase()
    )
    .join('');
}
