import React from 'react';

import type { Attachment } from '../pm-node-types.js';

export type PromptInputAreaProps = {
  busy?: boolean;
  readonly?: boolean;
  placeholder?: string;
  hasSelectedNode?: boolean;
  maxLength: number;
  onChange: (value: string) => void;
  onSubmit: () => void;
  onRemoveAttachment?: (id: string) => void;
  value: string;
  busyValue?: string;
  onCancel?: () => void;
  onClose?: () => void;
  zIndex: number;
  dataHook: string;
  minHeight?: string;
  forceMultiline?: boolean;
  attachments?: Attachment[];
  className?: string;
  style?: React.CSSProperties;
  presetBarComponent?: React.ReactNode;
  actionBarComponent?: React.ReactNode;
  fileUploadFn?: () => Promise<void>;
};

export type PromptInputAreaRef = {
  focus: () => void;
};

export function useAutoHeight({
  inputRef,
  value,
  forceMultiline,
  baseLineHeight,
  minHeight,
}: {
  inputRef: React.RefObject<HTMLTextAreaElement | null>;
  value: string;
  forceMultiline: boolean;
  baseLineHeight: number;
  minHeight?: string;
}) {
  const hiddenInputRef = React.useRef<HTMLTextAreaElement>(null);
  const [isMultiline, setIsMultiline] = React.useState(false);

  React.useLayoutEffect(() => {
    if (inputRef.current && hiddenInputRef.current) {
      const newHeight = Math.min(inputRef.current.scrollHeight, 216);
      inputRef.current.style.height = `${newHeight}px`;

      const singleLineHeightThreshold = 25;
      const hasNewlines = value.includes('\n');
      const exceedsHeight = hiddenInputRef.current.scrollHeight > singleLineHeightThreshold;
      const shouldBeMultiline = forceMultiline || hasNewlines || exceedsHeight;

      if (forceMultiline) {
        setIsMultiline(true);
        const height = minHeight || '66px';
        inputRef.current.style.height = height;
        inputRef.current.style.minHeight = height;
      } else if (value === '' || !exceedsHeight) {
        setIsMultiline(false);
        inputRef.current.style.height = `${baseLineHeight}px`;
        inputRef.current.style.minHeight = '';
      } else if (shouldBeMultiline) {
        setIsMultiline(true);
        if (minHeight) {
          inputRef.current.style.minHeight = minHeight;
        }
      }
    }
  }, [value, forceMultiline, minHeight]);

  return { isMultiline, hiddenInputRef };
}

export function useKeyboardHandler({
  busy,
  onEsc,
  onEnter,
}: {
  busy?: boolean;
  onEsc?: () => void;
  onEnter: () => void;
}) {
  const onKeyDown = React.useCallback(
    (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
      if (e.key === 'Escape') {
        if (busy) {
          e.stopPropagation();
          onEsc?.();
          return;
        }
      }

      if (!e.shiftKey && e.key === 'Enter') {
        e.stopPropagation();
        e.preventDefault();
        if (!busy) {
          onEnter();
        }
        return;
      }

      if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.key)) {
        e.stopPropagation();
      }
    },
    [busy, onEsc, onEnter]
  );

  return { onKeyDown };
}

export function useFocusCallback(inputRef: React.RefObject<HTMLTextAreaElement | null>) {
  const focus = React.useCallback(
    (retries = 100) => {
      setTimeout(() => {
        inputRef.current?.focus();
        if (document.activeElement !== inputRef.current && retries > 0) {
          focus(retries - 1);
        }
      }, 10);
    },
    [inputRef]
  );

  return { focus };
}
