/**
 * Shared URL resolver functions for media assets.
 * Used by both Editor and Viewer to resolve media URLs consistently.
 */

export const getImageUrl = ({ file_name }: { file_name: string }): string =>
  `https://static.wixstatic.com/media/${file_name}`;

export const getVideoUrl = ({ pathname }: { pathname: string }): string =>
  `https://video.wixstatic.com/${pathname}`;

export const getThumbnailUrl = ({ pathname }: { pathname: string }): string => {
  const prefix = pathname.startsWith('media/') ? '' : 'media/';
  return `https://static.wixstatic.com/${prefix}${pathname}`;
};

export const getAudioUrl = ({ id }: { id: string }): string => `https://static.wixstatic.com/${id}`;
