export const WidgetPromptInputArea = React.forwardRef<PromptInputAreaRef, PromptInputAreaProps>(
  (
    {
      busy,
      readonly,
      placeholder,
      maxLength,
      onChange,
      onSubmit,
      onRemoveAttachment,
      hasSelectedNode,
      value,
      busyValue,
      onCancel,
      onClose,
      dataHook,
      minHeight,
      attachments = [],
      className,
      style,
      presetBarComponent,
      actionBarComponent,
      fileUploadFn,
    },
    ref
  ) => {
    const { t } = useContext(RicosContext);
    const inputRef = React.useRef<HTMLTextAreaElement>(null);

    const { focus } = useFocusCallback(inputRef);

    React.useImperativeHandle(ref, () => ({ focus }), [focus]);

    const showPresetBar = Boolean(presetBarComponent);
    const allowFileUpload = Boolean(fileUploadFn);
    const showAttachments = allowFileUpload && attachments.length > 0;

    const { hiddenInputRef } = useAutoHeight({
      inputRef,
      value,
      forceMultiline: false,
      minHeight,
      baseLineHeight: 18,
    });

    const [hasError, setHasError] = React.useState(false);

    React.useEffect(() => {
      if (value) {
        setHasError(false);
      }
    }, [value]);

    const handleSubmit = React.useCallback(() => {
      if (!value.trim()) {
        setHasError(true);
        return;
      }
      setHasError(false);
      onSubmit();
    }, [value, onSubmit]);

    const { onKeyDown } = useKeyboardHandler({
      busy,
      onEsc: () => {
        onCancel?.();
        onClose?.();
      },
      onEnter: handleSubmit,
    });

    const displayedValue = busy ? (busyValue ?? t('AIPlugin_Input_Loading_Text')) : value;
    const displayedPlaceholder = t(placeholder ?? 'AIPlugin_Input_Placeholder_Text');

    return (
      <div className={classNames(classes.root, className)} style={style}>
        <Box verticalAlign="middle" align="space-between" marginBlockEnd="6px">
          <Box verticalAlign="middle" align="space-between" gap={1}>
            <SparklesFilledWithGradient style={{ marginInlineEnd: '3px' }} />
            <Heading size="medium">
              {hasSelectedNode
                ? t('AIWidget_PromptInput_Title_Refine')
                : t('AIWidget_PromptInput_Title_Create')}
            </Heading>
            <InfoIcon content={t('AIWidget_PromptInput_Disclaimer')} />
          </Box>
          {onClose && <CloseButton skin="dark" size="large" onClick={onClose} />}
        </Box>

        {presetBarComponent}

        <FormField
          status={hasError ? 'error' : undefined}
          statusMessage={hasError ? t('AIWidget_PromptInput_Error_EmptyPrompt') : undefined}
        >
          <div
            className={classNames(classes.inputContainer, { [classes.error]: hasError })}
            onClick={e => {
              if (e.target instanceof Element && e.target.closest('button,input,textarea')) {
                return;
              }

              inputRef.current?.focus();
            }}
          >
            {showAttachments && (
              <div className={classes.topBar}>
                {showAttachments ? (
                  <AttachmentBar
                    attachments={attachments}
                    onRemove={id => onRemoveAttachment?.(id)}
                  />
                ) : null}
              </div>
            )}

            <div className={classes.stack}>
              <textarea
                ref={hiddenInputRef}
                className={classNames(classes.textInput, classes.hiddenInput, {
                  [classes.allowFileUpload]: allowFileUpload,
                })}
                value={displayedValue}
                readOnly
                {...({ inert: '' } as React.HTMLAttributes<HTMLTextAreaElement>)}
              />
              <textarea
                ref={inputRef}
                data-hook={dataHook}
                name={displayedPlaceholder}
                className={classNames(classes.textInput, {
                  [classes.hasTopBar]: showPresetBar || showAttachments,
                  [classes.allowFileUpload]: allowFileUpload,
                  [classes.disabled]: busy,
                })}
                placeholder={displayedPlaceholder}
                value={displayedValue}
                onChange={e => {
                  if (hasError && e.target.value) {
                    setHasError(false);
                  }
                  onChange?.(e.target.value);
                }}
                maxLength={maxLength}
                readOnly={readonly}
                disabled={busy}
                onKeyDown={onKeyDown}
              />
            </div>

            <div
              className={classNames(classes.actionsContainer, {
                [classes.allowFileUpload]: allowFileUpload,
              })}
            >
              {(fileUploadFn || actionBarComponent) && (
                <Box gap="6px" verticalAlign="middle" align="space-between">
                  {fileUploadFn && (
                    <IconButton
                      onClick={fileUploadFn}
                      priority="secondary"
                      size="small"
                      disabled={busy}
                    >
                      <Add />
                    </IconButton>
                  )}
                  {actionBarComponent}
                </Box>
              )}
              <Box marginInlineStart="auto" gap="12px" verticalAlign="middle">
                {busy ? (
                  <IconButton size="small" onClick={onCancel} priority="secondary">
                    <Stop />
                  </IconButton>
                ) : (
                  <Button size="small" skin="ai" onClick={handleSubmit} disabled={readonly}>
                    {hasSelectedNode
                      ? t('AIWidget_PromptInput_Button_Regenerate')
                      : t('AIWidget_PromptInput_Button_Generate')}
                  </Button>
                )}
              </Box>
            </div>
          </div>
        </FormField>
      </div>
    );
  }
);

WidgetPromptInputArea.displayName = 'WidgetPromptInputArea';
